1	import { useMemo, useState } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import { useLocation } from "wouter";
4	import { getCurrentMerchantId } from "@/lib/auth";
5	import { useNotifications } from "@/components/notification-system";
6	import {
7	  type Timeframe,
8	  buildBuckets,
9	  periodWindow,
10	  collectedCents,
11	  growthPct,
12	} from "@/lib/property-dashboard-data";
13	import {
14	  DesktopPageScaffold,
15	  type DesktopRoutePageProps,
16	} from "../DesktopPageScaffold";
17	
18	/* ── Retail palette (from the desktop design tokens) ── */
19	const ACCENT = "#5E9EFF";
20	const ACCENT_SOFT = "#7FB2FF";
21	const NAV_DIM = "#4A86F0";
22	const ACTIVE = "#66A9FF";
23	const TEXT_SOFT = "#F4F6FF";
24	const NAVY = "#000F3F";
25	const CHIP = "#0F1747";
26	const BAR_DIM = "rgba(94,158,255,0.32)";
27	const GREEN = "#35D07F";
28	const RED = "#F0656C";
29	const AMBER = "#F0A34E";
30	
31	const RANGES: Timeframe[] = ["day", "week", "month", "year"];
32	const RANGE_UNIT: Record<Timeframe, string> = {
33	  day: "hour",
34	  week: "day",
35	  month: "week",
36	  year: "month",
37	};
38	
39	/* ── formatting helpers ── */
40	const centsOf = (price: unknown) =>
41	  Math.round(parseFloat(String(price ?? "0")) * 100) || 0;
42	const fmtDollars = (cents: number) =>
43	  "$" + Math.round(cents / 100).toLocaleString("en-NZ");
44	const money2 = (cents: number) =>
45	  "$" +
46	  (cents / 100).toLocaleString("en-NZ", {
47	    minimumFractionDigits: 2,
48	    maximumFractionDigits: 2,
49	  });
50	
51	function initials(name: string): string {
52	  const parts = String(name ?? "").trim().split(/\s+/).filter(Boolean);
53	  if (parts.length === 0) return "–";
54	  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
55	  return (parts[0][0] + parts[1][0]).toUpperCase();
56	}
57	
58	function timeAgo(iso: string): string {
59	  const then = new Date(iso).getTime();
60	  if (!Number.isFinite(then)) return "";
61	  const s = Math.max(0, Math.floor((Date.now() - then) / 1000));
62	  if (s < 60) return `${s}s ago`;
63	  const m = Math.floor(s / 60);
64	  if (m < 60) return `${m}m ago`;
65	  const h = Math.floor(m / 60);
66	  if (h < 24) return `${h}h ago`;
67	  return `${Math.floor(h / 24)}d ago`;
68	}
69	
70	const prettyMethod = (m: unknown) =>
71	  String(m ?? "card").replace(/_/g, " ").toLowerCase();
72	
73	function statusLabel(status: string): string {
74	  switch (status) {
75	    case "completed":
76	      return "payment received";
77	    case "pending":
78	    case "processing":
79	      return "awaiting payment";
80	    case "failed":
81	      return "payment failed";
82	    case "refunded":
83	      return "refunded";
84	    case "partially_refunded":
85	      return "partly refunded";
86	    default:
87	      return status;
88	  }
89	}
90	
91	function hour12(h: number): number {
92	  const hr = h % 12;
93	  return hr === 0 ? 12 : hr;
94	}
95	const meridiem = (h: number) => (h < 12 ? "am" : "pm");
96	
97	/* ── data-derived view model ── */
98	interface Tx {
99	  id: number | string;
100	  status: string;
101	  itemName?: string;
102	  paymentMethod?: string;
103	  price?: string;
104	  createdAt: string;
105	}
106	
107	function useRetailHomeModel(tf: Timeframe, selBar: number) {
108	  const merchantId = getCurrentMerchantId();
109	
110	  const merchantQuery = useQuery<any>({
111	    queryKey: ["/api/merchants", merchantId, "profile"],
112	    queryFn: async () => {
113	      const token = localStorage.getItem("authToken");
114	      const res = await fetch(`/api/merchants/${merchantId}/profile`, {
115	        headers: { Authorization: `Bearer ${token}` },
116	      });
117	      if (!res.ok) throw new Error("Failed to fetch merchant");
118	      return res.json();
119	    },
120	    enabled: !!merchantId,
121	  });
122	
123	  const txQuery = useQuery<Tx[]>({
124	    queryKey: ["/api/merchants", merchantId, "transactions"],
125	    queryFn: async () => {
126	      const token = localStorage.getItem("authToken");
127	      const res = await fetch(`/api/merchants/${merchantId}/transactions`, {
128	        headers: { Authorization: `Bearer ${token}` },
129	      });
130	      if (!res.ok) throw new Error("Failed to fetch transactions");
131	      return res.json();
132	    },
133	    staleTime: 30000,
134	    retry: false,
135	    enabled: !!merchantId,
136	  });
137	
138	  const transactions = txQuery.data ?? [];
139	
140	  const model = useMemo(() => {
141	    /* Adapt to the shared invoice-shaped helpers: a completed transaction is a
142	       "paid invoice" collected at createdAt. */
143	    const sales = transactions.map((tx) => ({
144	      status: tx.status === "completed" ? "paid" : tx.status,
145	      createdAt: tx.createdAt,
146	      paidAt: tx.createdAt,
147	      amountCents: centsOf(tx.price),
148	    }));
149	
150	    const win = periodWindow(tf);
151	    const collected = collectedCents(sales, win.start, win.end);
152	    const growth = growthPct(
153	      collected,
154	      collectedCents(sales, win.prevStart, win.prevEnd),
155	    );
156	
157	    const buckets = buildBuckets(sales, tf);
158	    const total = buckets.reduce((a, b) => a + b.valueCents, 0);
159	    const maxVal = Math.max(...buckets.map((b) => b.valueCents), 1);
160	    let peak = 0;
161	    buckets.forEach((b, i) => {
162	      if (b.valueCents > buckets[peak].valueCents) peak = i;
163	    });
164	    const selectedIdx =
165	      selBar >= 0 && selBar < buckets.length ? selBar : peak;
166	    const selected = buckets[selectedIdx];
167	
168	    /* Store-health: today's transactions. Awaiting = live mid-scan (any time). */
169	    const dayStart = new Date();
170	    dayStart.setHours(0, 0, 0, 0);
171	    const today = transactions.filter(
172	      (t) => new Date(t.createdAt) >= dayStart,
173	    );
174	    const awaiting = transactions.filter(
175	      (t) => t.status === "pending" || t.status === "processing",
176	    );
177	    const doneToday = today.filter((t) => t.status === "completed");
178	    const failedToday = today.filter((t) => t.status === "failed");
179	
180	    const awaitingCents = awaiting.reduce((s, t) => s + centsOf(t.price), 0);
181	    const doneCents = doneToday.reduce((s, t) => s + centsOf(t.price), 0);
182	    const avgCents = doneToday.length
183	      ? Math.round(doneCents / doneToday.length)
184	      : 0;
185	    const failedCents = failedToday.reduce((s, t) => s + centsOf(t.price), 0);
186	
187	    /* Busiest hour from today's completed sales. */
188	    const byHour = new Map<number, { count: number; cents: number }>();
189	    doneToday.forEach((t) => {
190	      const h = new Date(t.createdAt).getHours();
191	      const b = byHour.get(h) ?? { count: 0, cents: 0 };
192	      b.count += 1;
193	      b.cents += centsOf(t.price);
194	      byHour.set(h, b);
195	    });
196	    const hourList = Array.from(byHour.entries()).map(([h, v]) => ({
197	      h,
198	      count: v.count,
199	      cents: v.cents,
200	    }));
201	    const busiest = hourList.length
202	      ? hourList.reduce((best, cur) => (cur.count > best.count ? cur : best))
203	      : null;
204	
205	    const health = [
206	      {
207	        k: "awaiting",
208	        v: money2(awaitingCents),
209	        n: String(awaiting.length),
210	        label: "awaiting payment",
211	        col: TEXT_SOFT,
212	      },
213	      {
214	        k: "avg",
215	        v: money2(avgCents),
216	        n: String(doneToday.length),
217	        label: "avg sale · transactions",
218	        col: TEXT_SOFT,
219	      },
220	      {
221	        k: "failed",
222	        v: money2(failedCents),
223	        n: String(failedToday.length),
224	        label: "failed",
225	        col: ACCENT,
226	      },
227	    ];
228	
229	    const detail: Record<
230	      string,
231	      { title: string; rows: { name: string; sub: string; amt: string; col: string }[] }
232	    > = {
233	      awaiting: {
234	        title: "AWAITING PAYMENT — CUSTOMER MID-SCAN",
235	        rows: awaiting.slice(0, 6).map((t) => ({
236	          name: t.itemName || "sale",
237	          sub: `created ${timeAgo(t.createdAt)}`,
238	          amt: money2(centsOf(t.price)),
239	          col: TEXT_SOFT,
240	        })),
241	      },
242	      avg: {
243	        title: "TODAY BY THE NUMBERS",
244	        rows: [
245	          {
246	            name: "transactions",
247	            sub: "today so far",
248	            amt: String(doneToday.length),
249	            col: TEXT_SOFT,
250	          },
251	          {
252	            name: "average sale",
253	            sub: "per transaction",
254	            amt: money2(avgCents),
255	            col: TEXT_SOFT,
256	          },
257	          ...(busiest
258	            ? [
259	                {
260	                  name: "busiest hour",
261	                  sub: `${hour12(busiest.h)}–${hour12(busiest.h + 1)}${meridiem(busiest.h)} · ${busiest.count} sale${busiest.count === 1 ? "" : "s"}`,
262	                  amt: money2(busiest.cents),
263	                  col: TEXT_SOFT,
264	                },
265	              ]
266	            : []),
267	        ],
268	      },
269	      failed: {
270	        title: "FAILED — RETRY OR RE-SEND",
271	        rows: failedToday.slice(0, 6).map((t) => ({
272	          name: t.itemName || "sale",
273	          sub: `card declined · ${timeAgo(t.createdAt)}`,
274	          amt: money2(centsOf(t.price)),
275	          col: ACCENT,
276	        })),
277	      },
278	    };
279	
280	    /* Recent sales feed — real transactions, newest first. */
281	    const recent = [...transactions]
282	      .sort(
283	        (a, b) =>
284	          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
285	      )
286	      .map((t) => ({
287	        id: t.id,
288	        initials: initials(t.itemName || "sale"),
289	        name: t.itemName || "sale",
290	        sub: `${prettyMethod(t.paymentMethod)} · ${timeAgo(t.createdAt)}`,
291	        amt: money2(centsOf(t.price)),
292	        status: statusLabel(t.status),
293	      }));
294	
295	    return {
296	      collected,
297	      growth,
298	      buckets,
299	      total,
300	      maxVal,
301	      peak,
302	      selectedIdx,
303	      selected,
304	      health,
305	      detail,
306	      recent,
307	    };
308	  }, [transactions, tf, selBar]);
309	
310	  return {
311	    merchant: merchantQuery.data,
312	    isLoading: txQuery.isLoading,
313	    isError: txQuery.isError,
314	    refetch: txQuery.refetch,
315	    ...model,
316	  };
317	}
318	
319	/* ── page ── */
320	export default function DesktopRetailHome(props: DesktopRoutePageProps) {
321	  const [, setLocation] = useLocation();
322	  const [tf, setTf] = useState<Timeframe>("week");
323	  const [selBar, setSelBar] = useState(-1);
324	  const [healthBox, setHealthBox] = useState<string | null>(null);
325	  const [notifOpen, setNotifOpen] = useState(false);
326	  const [search, setSearch] = useState("");
327	
328	  const m = useRetailHomeModel(tf, selBar);
329	  const { notifications } = useNotifications();
330	
331	  const breakdownAmt = m.selected ? fmtDollars(m.selected.valueCents) : "$0";
332	  const avgCents = m.buckets.length
333	    ? Math.round(m.total / m.buckets.length)
334	    : 0;
335	  const sharePct =
336	    m.total > 0 && m.selected
337	      ? Math.round((m.selected.valueCents / m.total) * 100)
338	      : 0;
339	  const bestLabel =
340	    m.selected && m.selectedIdx === m.peak ? ` · best ${RANGE_UNIT[tf]}` : "";
341	
342	  const filteredRecent = m.recent.filter((r) =>
343	    (r.name + " " + r.sub).toLowerCase().includes(search.toLowerCase()),
344	  );
345	
346	  const notifDot = (type: string) =>
347	    type === "success"
348	      ? GREEN
349	      : type === "error"
350	        ? RED
351	        : type === "warning"
352	          ? AMBER
353	          : ACCENT;
354	
355	  const go = (path: string) => () => setLocation(path);
356	
357	  return (
358	    <DesktopPageScaffold
